//! The Emoji & Symbols catalogue behind ⌃⌘Space: the Unicode emoji with their
//! CLDR names and keywords, the Mac picker's categories, search, skin-tone
//! variants and the Frequently Used list.
//!
//! The data is generated by `scripts/emoji/generate_emoji_data.py` from
//! Unicode's `emoji-test.txt` and CLDR's English annotations (both under the
//! Unicode License v3) and embedded as one tab-separated file.

use std::path::{Path, PathBuf};
use std::sync::OnceLock;

const DATA: &str = include_str!("../assets/emoji.tsv");

/// How many Frequently Used emoji the picker keeps.
pub const MAX_RECENTS: usize = 32;
const MAX_RECENT_FILE_BYTES: u64 = 16 * 1024;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub enum Category {
    People,
    Nature,
    Food,
    Activity,
    Travel,
    Objects,
    Symbols,
    Flags,
}

impl Category {
    pub const ALL: [Self; 8] = [
        Self::People,
        Self::Nature,
        Self::Food,
        Self::Activity,
        Self::Travel,
        Self::Objects,
        Self::Symbols,
        Self::Flags,
    ];

    /// The section title, as the Mac picker words it.
    pub const fn label(self) -> &'static str {
        match self {
            Self::People => "Smileys & People",
            Self::Nature => "Animals & Nature",
            Self::Food => "Food & Drink",
            Self::Activity => "Activity",
            Self::Travel => "Travel & Places",
            Self::Objects => "Objects",
            Self::Symbols => "Symbols",
            Self::Flags => "Flags",
        }
    }

    fn parse(value: &str) -> Option<Self> {
        Some(match value {
            "People" => Self::People,
            "Nature" => Self::Nature,
            "Food" => Self::Food,
            "Activity" => Self::Activity,
            "Travel" => Self::Travel,
            "Objects" => Self::Objects,
            "Symbols" => Self::Symbols,
            "Flags" => Self::Flags,
            _ => return None,
        })
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Entry {
    pub glyph: &'static str,
    pub category: Category,
    pub name: &'static str,
    keywords: &'static str,
    variants: &'static str,
}

impl Entry {
    pub fn keywords(&self) -> impl Iterator<Item = &'static str> {
        self.keywords.split(" | ").filter(|word| !word.is_empty())
    }

    /// The five skin-tone forms, light to dark; empty for emoji without them.
    pub fn variants(&self) -> impl Iterator<Item = &'static str> {
        self.variants.split(' ').filter(|word| !word.is_empty())
    }

    pub fn has_variants(&self) -> bool {
        !self.variants.is_empty()
    }
}

/// Every emoji, in the Unicode (CLDR) order the Mac picker uses.
pub fn catalog() -> &'static [Entry] {
    static CATALOG: OnceLock<Vec<Entry>> = OnceLock::new();
    CATALOG.get_or_init(|| {
        DATA.lines()
            .filter_map(|line| {
                let mut fields = line.split('\t');
                let glyph = fields.next()?;
                let category = Category::parse(fields.next()?)?;
                let name = fields.next()?;
                Some(Entry {
                    glyph,
                    category,
                    name,
                    keywords: fields.next().unwrap_or(""),
                    variants: fields.next().unwrap_or(""),
                })
            })
            .collect()
    })
}

pub fn in_category(category: Category) -> impl Iterator<Item = &'static Entry> {
    catalog()
        .iter()
        .filter(move |entry| entry.category == category)
}

pub fn find(glyph: &str) -> Option<&'static Entry> {
    catalog().iter().find(|entry| entry.glyph == glyph)
}

/// Emoji matching every word of `query`, best match first. A word matches a
/// name or keyword by prefix or as part of a longer word; the order within
/// equal scores is the catalogue's.
pub fn search(query: &str, limit: usize) -> Vec<&'static Entry> {
    let query = query.trim().to_lowercase();
    if query.is_empty() {
        return Vec::new();
    }
    let words: Vec<&str> = query.split_whitespace().collect();
    let mut scored: Vec<(u32, usize, &'static Entry)> = catalog()
        .iter()
        .enumerate()
        .filter_map(|(index, entry)| {
            score(entry, &query, &words).map(|score| (score, index, entry))
        })
        .collect();
    scored.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
    scored
        .into_iter()
        .take(limit)
        .map(|(_, _, entry)| entry)
        .collect()
}

fn score(entry: &Entry, query: &str, words: &[&str]) -> Option<u32> {
    let name = entry.name.to_lowercase();
    let mut total = if name == query {
        200
    } else if name.starts_with(query) {
        120
    } else {
        0
    };
    for word in words {
        let mut best = 0;
        for part in name.split(|c: char| !c.is_alphanumeric()) {
            if part == *word {
                best = best.max(60);
            } else if part.starts_with(word) {
                best = best.max(45);
            } else if part.contains(word) {
                best = best.max(20);
            }
        }
        for keyword in entry.keywords() {
            let keyword = keyword.to_lowercase();
            if keyword == *word {
                best = best.max(40);
            } else if keyword.starts_with(word) {
                best = best.max(30);
            } else if keyword.contains(word) {
                best = best.max(10);
            }
        }
        if best == 0 {
            return None;
        }
        total += best;
    }
    Some(total)
}

/// The Frequently Used list: how many times each emoji was chosen, most used
/// first (the latest choice wins ties).
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct Recents {
    entries: Vec<(String, u32)>,
}

impl Recents {
    pub fn default_path() -> Option<PathBuf> {
        let base = std::env::var_os("XDG_STATE_HOME")
            .map(PathBuf::from)
            .filter(|path| path.is_absolute())
            .or_else(|| {
                std::env::var_os("HOME")
                    .map(PathBuf::from)
                    .filter(|path| path.is_absolute())
                    .map(|home| home.join(".local/state"))
            })?;
        Some(base.join("rmac/emoji-recents"))
    }

    /// A missing, oversized or damaged file is an empty list.
    pub fn load(path: &Path) -> Self {
        let Ok(metadata) = std::fs::metadata(path) else {
            return Self::default();
        };
        if metadata.len() > MAX_RECENT_FILE_BYTES {
            return Self::default();
        }
        let Ok(text) = std::fs::read_to_string(path) else {
            return Self::default();
        };
        let entries = text
            .lines()
            .filter_map(|line| {
                let (count, glyph) = line.split_once('\t')?;
                let count = count.parse::<u32>().ok()?;
                find(glyph).map(|entry| (entry.glyph.to_owned(), count))
            })
            .take(MAX_RECENTS)
            .collect();
        Self { entries }
    }

    pub fn save(&self, path: &Path) -> std::io::Result<()> {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        let text: String = self
            .entries
            .iter()
            .map(|(glyph, count)| format!("{count}\t{glyph}\n"))
            .collect();
        let temporary = path.with_extension("tmp");
        std::fs::write(&temporary, text)?;
        std::fs::rename(&temporary, path)
    }

    /// Count a choice; it moves ahead of every emoji with the same count.
    pub fn record(&mut self, glyph: &str) {
        let count = match self.entries.iter().position(|(known, _)| known == glyph) {
            Some(index) => self.entries.remove(index).1 + 1,
            None => 1,
        };
        let at = self
            .entries
            .iter()
            .position(|(_, other)| *other <= count)
            .unwrap_or(self.entries.len());
        self.entries.insert(at, (glyph.to_owned(), count));
        self.entries.truncate(MAX_RECENTS);
    }

    pub fn glyphs(&self) -> impl Iterator<Item = &str> {
        self.entries.iter().map(|(glyph, _)| glyph.as_str())
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_catalogue_loads_every_category() {
        assert!(catalog().len() > 1800);
        for category in Category::ALL {
            assert!(in_category(category).next().is_some(), "{category:?}");
        }
        assert_eq!(catalog()[0].glyph, "😀");
        assert_eq!(catalog()[0].name, "grinning face");
    }

    #[test]
    fn search_finds_by_name_and_keyword_best_first() {
        let hits = search("grinning", 5);
        assert_eq!(hits[0].glyph, "😀");
        // "cheerful" is only a keyword of the grinning face.
        assert!(search("cheerful", 20)
            .iter()
            .any(|entry| entry.glyph == "😀"));
        assert!(search("zzzzqqq", 5).is_empty());
        assert!(search("   ", 5).is_empty());
    }

    #[test]
    fn every_search_word_has_to_match() {
        let hits = search("red heart", 5);
        assert_eq!(hits[0].name, "red heart");
        assert!(hits.iter().all(|entry| {
            let text = format!(
                "{} {}",
                entry.name,
                entry.keywords().collect::<Vec<_>>().join(" ")
            );
            text.to_lowercase().contains("heart")
        }));
    }

    #[test]
    fn people_carry_five_skin_tones_and_others_none() {
        let wave = find("👋").expect("waving hand");
        assert_eq!(wave.variants().count(), 5);
        assert!(find("😀").is_some_and(|entry| !entry.has_variants()));
    }

    #[test]
    fn frequently_used_orders_by_count_then_recency() {
        let mut recents = Recents::default();
        recents.record("😀");
        recents.record("👋");
        recents.record("👋");
        recents.record("🎉");
        assert_eq!(recents.glyphs().collect::<Vec<_>>(), ["👋", "🎉", "😀"]);
    }

    #[test]
    fn recents_round_trip_and_ignore_damage() {
        let directory =
            std::env::temp_dir().join(format!("rmac-emoji-test-{}", std::process::id()));
        let path = directory.join("recents");
        let mut recents = Recents::default();
        recents.record("😀");
        recents.record("😀");
        recents.save(&path).unwrap();
        assert_eq!(Recents::load(&path), recents);
        std::fs::write(&path, "x\tnot a number\n9\tnot an emoji\n").unwrap();
        assert!(Recents::load(&path).is_empty());
        let _ = std::fs::remove_dir_all(directory);
    }
}
